
import './App.css';
import HeaderHero from './HeaderHero';
import capturingLiteracy from './capturingLiteracy.png';
import Image from 'react-bootstrap/Image';
import Footer from './Footer';

import ServiceCard from "./ServiceCard";
import { useEffect } from "react";
import { useLocation } from "react-router-dom";


export default function Home() {
const location = useLocation();

  useEffect(() => {
    if (location.state?.scrollTo) {
      const el = document.getElementById(location.state.scrollTo);
      if (el) {
        el.scrollIntoView({ behavior: "smooth" });
      }
    }
  }, [location]);


  return (
    <div>
      <HeaderHero image={capturingLiteracy} title={"Katie Lynch"} description={"Certified Academic Language Therapist | IEW Instructor | Dyslexia Specialist"} currentPageName={"Home"}  />
      <section id="bio" class="bio-section">
            <h2>About Katie Lynch</h2>
            <div className="bio-content">
              <div className="bio-image-wrapper">
                <Image
                  src="https://lh3.googleusercontent.com/a-/ALV-UjUgoM4CLOYApN3oXhKtgtbruhtm5ymFxY6IEO-uoyZToLRE8B4=s330-p-k-rw-no"
                  alt="Katie Lynch"
                  roundedCircle
                  className="bio-image"
                />
                
                <div className="bio-overlay" onClick={() => window.location.href = '/contact'}>
                  Contact Me
                </div>
              </div>
              <div className="bio-text">
                <p>
                    As a Certified Academic Language Therapist and the mother of 3 teenage boys - whom I have home-schooled at various 
                    times in their development –  I have <span class="highlight">first-hand</span> experience with the challenges that can accompany teaching children 
                    how to communicate via the written word. I am an Experienced IEW Instructor and trained in Sounds in Syllables (SIS), 
                    an Orton-Gillingham multisensory structured language approach to teaching reading, spelling, and writing. I teach group 
                    classes using IEW materials, as well as offer individual instruction on writing, grammar, and dyslexia therapy. 
                </p>
              </div>
            </div>
      </section>
      <section id="quote" class="quote-section">
            <h2>My Belief</h2>
            <p>
                "Many children struggle with writing not because they lack intelligence or creativity, 
                but because they have not yet mastered the essential building blocks that allow them 
                to express their thoughts clearly. When given a <span class="highlight">structured</span>, 
                incremental, and <span class="highlight">multisensory</span> approach, all students can gain 
                the skills and <span class="highlight">confidence</span> to communicate effectively in writing. 
                Through patience, understanding, and targeted instruction, even the most frustrated learners 
                can discover their <span class="highlight">voice</span> and become competent writers."
            </p>
            </section>

            
            <section className="services-preview quote-section" >
                <h2>Services</h2>
                <p>
                  As a Certified Academic Language Therapist with a deep understanding of various learning styles, 
                  I employ a <span class="highlight">compassionate</span> and <span class="highlight">tailored</span> approach to meet children where they are academically. 
                  I focus on each student’s strengths to help them build the confidence and independence needed to achieve 
                  academic success.  
                </p>
                <ServiceCard
                    title="Writing & Grammar Instruction"
                    description="Structured, step-by-step writing instruction that helps students build confidence and clarity in their communication."
                    image={capturingLiteracy}
                    link="/services/writing"
                />

                <ServiceCard
                    title="Dyslexia Therapy"
                    description="Multisensory, Orton-Gillingham based instruction designed to support students with dyslexia and reading challenges."
                    image={capturingLiteracy}
                    link="/services/dyslexia"
                    reverse
                />
            </section>
        
            <Footer />

    </div>
    
  );
}