import { useParams, Link } from 'react-router-dom';
import './App.css';
import HeaderHero from './HeaderHero';
import capturingLiteracy from './capturingLiteracy.png';
import Footer from './Footer';

export default function Service() {
  const { service } = useParams();

  // You can replace this with real data or fetch from JSON/API
  const servicesData = {
    'writing': {
      title: 'Writing & Grammar Instruction',
      description: 'Structured, step-by-step writing instruction that helps students build confidence and clarity in their communication.',
      courseDescription: 'This course provides structured, step-by-step writing instruction designed to help students build confidence and clarity in their communication. Through a combination of engaging lessons, interactive exercises, and personalized feedback, students will develop essential writing skills that enable them to express their thoughts effectively. The curriculum covers various aspects of writing, including grammar, sentence structure, organization, and style. By the end of the course, students will have the tools and confidence needed to communicate clearly and effectively in their writing.'
    },
    'dyslexia': {
      title: 'Dyslexia Support',
      description: 'Evidence-based strategies for students with dyslexia.',
      courseDescription: 'This course offers evidence-based strategies and interventions for students with dyslexia. It focuses on developing phonological awareness, decoding skills, and reading comprehension strategies. Students will learn techniques to overcome common challenges associated with dyslexia and build confidence in their reading abilities.'
    }
  };

  const currentService = servicesData[service?.toLowerCase()];

  if (!currentService) {
    return (
      <div style={{ padding: '2rem' }}>
        
        <HeaderHero
          image={capturingLiteracy}
          title={"Service not found"}
          description={"The requested service was not found."}
          currentPageName={"Service not found"}
        />
        <Link to="/services" >Back to Services</Link>
        
        <p style={{margin: "50px"}}>Service "{service}" not found.</p>
        <Footer />
      </div>
    );
  } else {
    return (
      <div style={{ padding: '2rem' }}>
        <HeaderHero
          image={capturingLiteracy}
          title={currentService.title}
          description={currentService.description}
          currentPageName={currentService.title}
        />

        
        <Link to="/services">Back to Services</Link>
        
        <section className="course-description">
          <h2>Course Details</h2>
          <p>{currentService.courseDescription}</p>
        </section>

        <Footer />
      </div>
    );
  }
}