import { useState } from 'react';
import './App.css';
import HeaderHero from './HeaderHero';
import capturingLiteracy from './capturingLiteracy.png';
import Footer from './Footer';
import { FontAwesomeIcon } from '@fortawesome/react-fontawesome';
import { faClock } from '@fortawesome/free-solid-svg-icons';

const truncateText = (text, maxLength = 300) => {
  if (text.length <= maxLength) return text;

  const trimmed = text.slice(0, maxLength);
  const lastSpace = trimmed.lastIndexOf(" ");

  return (lastSpace > 0 ? trimmed.slice(0, lastSpace) : trimmed) + "...";
};

export default function Blog() {

  const BlogsData = [
    {
      title: "Celebrating One Year of Huntsville's Garden Troll",
      description: "Lorem ipsum dolor sit amet, consectetur adipiscing elit, sed do eiusmod tempor incididunt ut labore et dolore magna aliqua. Ut enim ad minim veniam, quis nostrud exercitation ullamco laboris nisi ut aliquip ex ea commodo consequat. Duis aute irure dolor in reprehenderit in voluptate velit esse cillum dolore eu fugiat nulla pariatur. Excepteur sint occaecat cupidatat non proident, sunt in culpa qui officia deserunt mollit anim id est laborum.",
      preview: "...",
      date: "2024-05-01",
      file: "https://www.huntsville.org/blog/list/post/celebrating-one-year-of-huntsvilles-garden-troll/",
      image: "https://assets.simpleviewinc.com/simpleview/image/upload/c_fill,f_jpg,g_xy_center,h_563,q_65,w_1920,x_3000,y_1300/v1/clients/huntsville/HBG_5_10_25_10__e7c64bef-ec87-4749-9d8d-bbe5140be559.jpg",
      readTime: 3
    },
    {
      title: "The Science of Reading",
      description: "Why structured literacy works.",
      preview: "...",
      date: "2024-05-01",
      file: "/essays/science-of-reading.pdf",
      image: capturingLiteracy,
      readTime: 3
    },
   {
      title: "The Science of Reading",
      description: "Why structured literacy works.",
      preview: "...",
      date: "2024-05-01",
      file: "/essays/science-of-reading.pdf",
      image: capturingLiteracy,
      readTime: 3
    },
    {
      title: "Dyslexia Myths Debunked",
      description: "Common misconceptions.",
      preview: "Dyslexia is often misunderstood...",
      date: "2024-01-10",
      file: "/essays/dyslexia-myths.pdf",
      image: capturingLiteracy
    }
  ];

  const [search, setSearch] = useState("");
  const [sort, setSort] = useState("newest");

  const filteredBlogs = [...BlogsData]
    .filter(b =>
      b.title.toLowerCase().includes(search.toLowerCase()) ||
      b.description.toLowerCase().includes(search.toLowerCase())
    )
    .sort((a, b) => {
      switch (sort) {
        case "newest":
          return new Date(b.date) - new Date(a.date);
        case "oldest":
          return new Date(a.date) - new Date(b.date);
        case "az":
          return a.title.localeCompare(b.title);
        case "za":
          return b.title.localeCompare(a.title);
        default:
          return 0;
      }
    });

  return (
    <div>

      <HeaderHero
        image={capturingLiteracy}
        title={"Blog"}
        description={"Explore insights, strategies, and stories about literacy"}
        currentPageName={"Blog"}
      />

      {/* 🔍 SEARCH + FILTER */}
      <div className="essay-controls">
        <input
          type="text"
          placeholder="Search blog posts..."
          value={search}
          onChange={(e) => setSearch(e.target.value)}
        />

        <select value={sort} onChange={(e) => setSort(e.target.value)}>
          <option value="newest">Newest → Oldest</option>
          <option value="oldest">Oldest → Newest</option>
          <option value="az">A → Z</option>
          <option value="za">Z → A</option>
        </select>
      </div>

      {/* 📰 BLOG LIST */}
      <div className="blog-grid">
  {filteredBlogs.map((blog, index) => (
    <div key={index} className="blog-card">

      {/* IMAGE BACKGROUND */}
      <div
        className="blog-card-image"
        style={{ backgroundImage: `url(${blog.image})` }}
      >

        {/* OVERLAY CONTENT */}
        <div className="blog-overlay" onDoubleClick={() => window.open(blog.file, "_blank")}>
          <h2 className="blog-title">
            <a
              href={blog.file}
              
              target="_blank"
              rel="noopener noreferrer"
            >
              {truncateText(blog.title, 90)}
            </a>
          </h2>
          <div className="blog-meta">
            <FontAwesomeIcon icon={faClock} /> {blog.readTime} Min Read
          </div>

         
          <p>{truncateText(blog.description, 280)}</p>

          
        </div>
       
      </div>
    </div>
  ))}
</div>

      <Footer />
    </div>
  );
}