import { useState } from 'react';
import './App.css';
import HeaderHero from './HeaderHero';
import capturingLiteracy from './capturingLiteracy.png';
import Footer from './Footer';
import essay from "./essays/EnglishProposal.pdf"

export default function Essay() {

  const essaysData = [
  {
    title: "2026 North Alabama Undergraduate Writing Conference Proposal",
    description: "In my researched-based personal essay, I share my grandfather’s personal experience and wisdom about the importance of curiosity, the ability to learn anything through reading, and the value of historical knowledge.",
    preview: "Learning from the mistakes we make in life is essential to our growth. Even more essential is learning from the mistakes our elders have made, retaining and applying their wisdom in our own lives...",
    date: "2026-04-08",
    file: essay,
    featured: true
  },
  {
    title: "The Science of Reading",
    description: "Why structured literacy works.",
    preview: "Reading is a complex cognitive process that involves decoding, comprehension, and language structure...",
    date: "2024-05-01",
    file: "/essays/science-of-reading.pdf",
    featured: false
  },
  {
    title: "Helping Struggling Readers",
    description: "Tools and strategies.",
    preview: "Many students face challenges when learning to read, but with the right tools and targeted instruction...",
    date: "2024-03-15",
    file: "/essays/struggling-readers.pdf",
    featured: false
  },
  {
    title: "Dyslexia Myths Debunked",
    description: "Common misconceptions.",
    preview: "Dyslexia is often misunderstood. This essay explores the truth behind common myths...",
    date: "2024-01-10",
    file: "/essays/dyslexia-myths.pdf",
    featured: false
  }
];

const featuredEssay = essaysData.find(e => e.featured);
const otherEssays = essaysData.filter(e => !e.featured);




  const [search, setSearch] = useState("");
  const [sort, setSort] = useState("newest");

  const filteredEssays = [...otherEssays]
  .filter(e =>
    e.title.toLowerCase().includes(search.toLowerCase()) ||
    e.description.toLowerCase().includes(search.toLowerCase())
  )
  .sort((a, b) => {
    switch (sort) {
      case "newest":
        return new Date(b.date) - new Date(a.date);
      case "oldest":
        return new Date(a.date) - new Date(b.date);
      case "az":
        return a.title.localeCompare(b.title);
      case "za":
        return b.title.localeCompare(a.title);
      default:
        return 0;
    }
  });

  return (
    <div>

      <HeaderHero
        image={capturingLiteracy}
        title={"Essay of the Month"}
        description={"Read the latest essay written by my students"}
        currentPageName={"Essay of the Month"}
      />

      
      <section className="essay-hero">
        <div className="essay-preview">
          <a
            href={featuredEssay.file}
            target="_blank"
            rel="noopener noreferrer"
            className="preview-link"
          >
            <div className="preview-text">
              {featuredEssay.preview}
            </div>

            <div className="preview-overlay">
              <span>View Essay</span>
            </div>
          </a>
        </div>

        <div className="essay-info">
          <h1>{featuredEssay.title}</h1>
          <p>{featuredEssay.description}</p>
        </div>
      </section>

      {/* 🔍 SEARCH + FILTER */}
      <div className="essay-controls">
        <input
          type="text"
          placeholder="Search essays..."
          value={search}
          onChange={(e) => setSearch(e.target.value)}
        />

        <select value={sort} onChange={(e) => setSort(e.target.value)}>
          <option value="newest">Newest → Oldest</option>
          <option value="oldest">Oldest → Newest</option>
          <option value="az">A → Z</option>
          <option value="za">Z → A</option>
        </select>
      </div>

      
      <div className="essay-container">
        {filteredEssays.map((essay, index) => (
          <a
            key={index}
            href={essay.file}
            target="_blank"
            rel="noopener noreferrer"
            className="essay-card-link"
          >
            <div className="essay-card">
              <div className="essay-title">{essay.title}</div>
              <div className="essay-date">{essay.date}</div>

              <p className="essay-preview-text">
                {essay.preview}
              </p>

              <div className="essay-hover">
                View Essay
              </div>
            </div>
          </a>
        ))}
      </div>

      <Footer />

    </div>
  );
}